UPDATE news_editorial_articles SET image_url='https://mgfitclub.ir/assets/news/editorial/24-training-shoes.jpg', image_alt='کفش و تجهیزات آماده برای جلسهٔ ورزشی بانوان' WHERE id='mg_editorial_mg_fitclub_shiraz_womens_fitness_guide';
INSERT OR IGNORE INTO news_editorial_articles (id,slug,title,summary,article_body,category,keywords,source_refs,image_url,image_alt,author_name,status,published_at,updated_at) VALUES
('mg_editorial_r2_strength_load_selection','choose-strength-training-weight-safely','برای شروع بدنسازی چه وزنه‌ای انتخاب کنیم؟ راهنمای انتخاب بار تمرین','وزنهٔ مناسب، وزنه‌ای است که حرکت را کنترل کنید و تکرارهای برنامه را با فرم قابل‌قبول انجام دهید؛ نه سنگین‌ترین وزنهٔ سالن.','## معیار ساده برای انتخاب وزنه در باشگاه بدنسازی بانوان'||char(10)||char(10)||'برای نخستین ست باری سبک انتخاب کنید و چند تکرار تمرینی انجام دهید. اگر دامنهٔ حرکت کوتاه می‌شود، بدن تاب می‌خورد یا برای جابه‌جایی وزنه نفس را حبس می‌کنید، بار احتمالاً برای شروع زیاد است. اگر همهٔ تکرارها بسیار آسان‌اند، پس از مشورت با مربی کمی آن را تنظیم کنید.'||char(10)||char(10)||'## بار تمرین را از روی کیفیت حرکت بسنجید'||char(10)||char(10)||'هدف، یک عدد ثابت برای همه نیست. دستگاه، دامنهٔ حرکت، تجربه و خستگی روزانه تفاوت ایجاد می‌کنند. در جلسه‌های اول یادگیری مسیر حرکت و تنظیم دستگاه مهم‌تر از ثبت رکورد است. چند تکرار را با ریتم کنترل‌شده اجرا کنید و بین ست‌ها به اندازه‌ای استراحت کنید که دوباره با فرم مناسب شروع کنید.'||char(10)||char(10)||'## چه زمانی وزنه را تغییر دهیم؟'||char(10)||char(10)||'اگر چند جلسه پیاپی حرکت روان و قابل‌تکرار بود، دربارهٔ افزایش کوچک بار یا تکرار با مربی گفت‌وگو کنید. درد تیز، بی‌حسی یا سرگیجه علامت فشار بیشتر نیست؛ تمرین را متوقف کنید و راهنمایی بگیرید. این مطلب نسخهٔ تمرین فردی یا تشخیص پزشکی نیست.','بدنسازی','["انتخاب وزنه بدنسازی","باشگاه بدنسازی بانوان شیراز","مربی بدنسازی بانوان"]','[{"title":"5 Things to Know About Creating an Effective Resistance Training Plan","publisher":"American College of Sports Medicine","url":"https://www.acsm.org/effective-resistance-training-program-infographic/","published":"2026-03"},{"title":"WHO Guidelines on Physical Activity and Sedentary Behaviour: At a Glance","publisher":"World Health Organization","url":"https://iris.who.int/bitstream/handle/10665/336656/9789240015128-eng.pdf","published":"2020-11-25"}]','https://mgfitclub.ir/assets/news/editorial/21-strength-coach.jpg','مربی بدنسازی بانوان در حال بررسی فرم اسکوات با دمبل سبک','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_machine_or_freeweights','gym-machines-vs-free-weights-for-beginners','دستگاه یا دمبل؛ برای شروع تمرین قدرتی کدام را انتخاب کنیم؟','هر دو ابزار می‌توانند بخشی از تمرین قدرتی باشند. انتخاب بهتر به هدف، راحتی تنظیم، مهارت حرکت و برنامهٔ قابل‌ادامه بستگی دارد.','## دستگاه و وزنهٔ آزاد چه تفاوتی دارند؟'||char(10)||char(10)||'دستگاه معمولاً مسیر حرکت را محدودتر و تنظیم بار را ساده‌تر می‌کند؛ دمبل آزادی بیشتری می‌دهد و به کنترل فردی بیشتری نیاز دارد. این تفاوت به‌تنهایی به معنی برتری همیشگی یک ابزار نیست. برای بسیاری از افراد تازه‌کار، آشنایی با تنظیم صندلی و دامنهٔ حرکت دستگاه نقطهٔ شروع قابل‌فهمی است.'||char(10)||char(10)||'## انتخاب را با هدف و دسترسی هماهنگ کنید'||char(10)||char(10)||'موضع به‌روز ACSM دربارهٔ تمرین مقاومتی می‌گوید برنامه‌های مؤثر می‌توانند با ابزارهای گوناگون طراحی شوند و پیچیدگی بیشتر الزاماً نتیجهٔ بهتر نمی‌دهد. در باشگاه شیراز از مربی بخواهید وسیله را متناسب با قد و دامنهٔ حرکت شما تنظیم کند؛ سپس ببینید کدام گزینه را با اطمینان و استمرار انجام می‌دهید.'||char(10)||char(10)||'## ترکیب ابزارها هم ممکن است'||char(10)||char(10)||'لازم نیست میان دستگاه و دمبل یکی را برای همیشه انتخاب کنید. برنامه می‌تواند برای الگوهای مختلف از هر دو استفاده کند؛ اما ترتیب و مقدار تمرین را مربی با توجه به تجربه و هدف شما تنظیم می‌کند. اگر تنظیم دستگاه یا نگه‌داشتن دمبل دردناک است، حرکت جایگزین بخواهید.','بدنسازی','["دستگاه یا دمبل","تمرین قدرتی مبتدیان","باشگاه بدنسازی شیراز"]','[{"title":"5 Things to Know About Creating an Effective Resistance Training Plan","publisher":"American College of Sports Medicine","url":"https://www.acsm.org/effective-resistance-training-program-infographic/","published":"2026-03"},{"title":"ACSM Position Stands","publisher":"American College of Sports Medicine","url":"https://acsm.org/education-resources/pronouncements-scientific-communications/position-stands/","published":"2026"}]','https://mgfitclub.ir/assets/news/editorial/25-machine-technique.jpg','مربی نحوهٔ تنظیم دستگاه تمرین قدرتی را به ورزشکار تازه‌کار نشان می‌دهد','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_failure_training_myth','do-you-need-to-train-to-failure-every-set','آیا باید در هر ست تا ناتوانی تمرین کرد؟ پاسخ کوتاه و کاربردی','رسیدن به ناتوانی لحظه‌ای شرط لازم هر ست نیست. کنترل حرکت و برنامه‌ای که بتوانید تداوم دهید مهم‌تر از تمام‌کردن هر تمرین با فرسودگی کامل است.','## ناتوانی عضلانی یعنی چه؟'||char(10)||char(10)||'در تمرین مقاومتی، ناتوانی لحظه‌ای زمانی است که فرد دیگر نتواند تکرار بعدی را با دامنه و فرم موردنظر انجام دهد. این مفهوم با خستگی معمول یا سوزش عضله یکی نیست و لازم نیست برای سنجش آن در هر ست فرم حرکت را خراب کنید.'||char(10)||char(10)||'## آنچه مرور ACSM در ۲۰۲۶ برجسته می‌کند'||char(10)||char(10)||'جمع‌بندی تازهٔ کالج پزشکی ورزشی آمریکا می‌گوید روش‌هایی مثل تمرین تا ناتوانی در افراد سالم به‌طور مداوم برتری نتیجه نشان نداده‌اند. این به معنی بی‌اثر بودن تمرین سخت نیست؛ بلکه بسیاری از افراد برای پیشرفت به روش افراطی یا پیچیده نیاز ندارند.'||char(10)||char(10)||'## نسخهٔ ایمن‌تر برای تمرین روزمره'||char(10)||char(10)||'ست را زمانی تمام کنید که هنوز قادر به حفظ فرم و کنترل هستید، به‌ویژه در تمرین‌های تازه یا دستگاه‌هایی که تنظیمشان را نمی‌شناسید. درد تیز، سرگیجه یا تغییر ناگهانی تکنیک را نادیده نگیرید. برای برنامهٔ شخصی با مربی و متخصص مربوط مشورت کنید.','بدنسازی','["تمرین تا ناتوانی عضلانی","تمرین قدرتی بانوان","راهنمای بدنسازی مبتدی"]','[{"title":"5 Things to Know About Creating an Effective Resistance Training Plan","publisher":"American College of Sports Medicine","url":"https://www.acsm.org/effective-resistance-training-program-infographic/","published":"2026-03"},{"title":"ACSM Position Stands","publisher":"American College of Sports Medicine","url":"https://acsm.org/education-resources/pronouncements-scientific-communications/position-stands/","published":"2026"}]','https://mgfitclub.ir/assets/news/editorial/40-dumbbell-coach.jpg','مربی خانم فرم دمبل‌زدن کنترل‌شده را به ورزشکار آموزش می‌دهد','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_two_strength_days','two-days-a-week-strength-training-plan','دو روز تمرین قدرتی در هفته را چطور برنامه‌ریزی کنیم؟','دو نوبت تمرین قدرتی می‌تواند در روزهای جدا از هم قرار بگیرد و گروه‌های اصلی عضلانی را پوشش دهد؛ جزئیات باید با توان و برنامهٔ زندگی هماهنگ شود.','## منظور از دو روز تمرین قدرتی چیست؟'||char(10)||char(10)||'راهنمای سازمان جهانی بهداشت برای بزرگسالان فعالیت‌های تقویت عضله که گروه‌های اصلی را درگیر می‌کنند، دست‌کم دو روز در هفته توصیه می‌کند. این چارچوب عمومی جمعیتی است، نه نسخهٔ یکسان برای هر فرد یا هر باشگاه.'||char(10)||char(10)||'## یک نمونهٔ ساده برای چیدن هفته'||char(10)||char(10)||'می‌توانید دو جلسهٔ تمام‌بدن را با فاصلهٔ مناسب در تقویم قرار دهید و روزهای دیگر پیاده‌روی یا فعالیت دلخواه داشته باشید. این فقط نمونه است؛ زمان و شدت را بر اساس تجربه، دسترسی و ترجیح خود تنظیم کنید. لازم نیست در هفتهٔ اول همهٔ روزها را با تمرین سنگین پر کنید.'||char(10)||char(10)||'## چه چیزی برنامه را قابل‌اجرا می‌کند؟'||char(10)||char(10)||'روز و ساعت رفت‌وآمد، شلوغی باشگاه، مدت جلسه و زمان استراحت را در نظر بگیرید. اگر برنامه با زندگی روزمره جور نباشد، کامل‌ترین جدول هم دوام نمی‌آورد. برای بانوان شیراز، ساعت کلاس و فضای تمرین را با برنامهٔ خود بسنجید.','راهنمای شیراز','["برنامه بدنسازی دو روز در هفته","باشگاه بانوان شیراز","تمرین قدرتی هفتگی"]','[{"title":"WHO Guidelines on Physical Activity and Sedentary Behaviour: At a Glance","publisher":"World Health Organization","url":"https://iris.who.int/bitstream/handle/10665/336656/9789240015128-eng.pdf","published":"2020-11-25"},{"title":"Physical activity","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/physical-activity","published":"2024-06-26"}]','https://mgfitclub.ir/assets/news/editorial/30-weekly-plan.jpg','ورزشکار در حال نوشتن برنامهٔ هفتگی تمرین','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_talk_test_intensity','talk-test-exercise-intensity-beginners','تست صحبت‌کردن؛ راه سادهٔ سنجش شدت هوازی برای تازه‌کارها','در فعالیت متوسط معمولاً می‌توانید حرف بزنید اما آوازخواندن سخت می‌شود؛ این نشانه جای ارزیابی تخصصی را نمی‌گیرد، ولی برای تنظیم فشار روزمره کمک‌کننده است.','## تست صحبت‌کردن چطور کار می‌کند؟'||char(10)||char(10)||'مرکز کنترل و پیشگیری بیماری‌های آمریکا تست صحبت‌کردن را راهی ساده برای فهم شدت نسبی فعالیت معرفی می‌کند. هنگام فعالیت متوسط، بیشتر افراد می‌توانند گفت‌وگو کنند اما آوازخواندن برایشان دشوار است. در شدت بالا معمولاً گفتن بیش از چند کلمه بدون مکث برای نفس سخت‌تر می‌شود.'||char(10)||char(10)||'## چرا شدت نسبی است؟'||char(10)||char(10)||'سرعتی که برای یک نفر سبک است ممکن است برای فرد دیگری سخت باشد. آمادگی فعلی، شیب مسیر، گرما و خواب شب قبل هم روی حس تلاش اثر می‌گذارند. به‌جای مقایسه با ورزشکار دیگر، واکنش بدن خود را ملاک بگیرید و شدت را تدریجی افزایش دهید.'||char(10)||char(10)||'## استفاده در کلاس یا تردمیل'||char(10)||char(10)||'برای شروع پیاده‌روی تند یا بخش هوازی کلاس، جمله‌ای کوتاه را امتحان کنید. اگر به‌سختی نفس می‌کشید سرعت را کم کنید. درد قفسهٔ سینه، غش، تنگی نفس غیرمعمول یا علائم نگران‌کننده نیازمند توقف و دریافت راهنمایی پزشکی است.','تمرین گروهی','["تست صحبت کردن ورزش","شدت تمرین هوازی","باشگاه ورزشی شیراز"]','[{"title":"Measuring Physical Activity Intensity","publisher":"Centers for Disease Control and Prevention","url":"https://www.cdc.gov/physicalactivity/basics/measuring/index.html","published":"2024-04-23"},{"title":"Physical Activity Guidelines for Adults","publisher":"Centers for Disease Control and Prevention","url":"https://www.cdc.gov/physical-activity-basics/guidelines/adults.html","published":"2023-12-20"}]','https://mgfitclub.ir/assets/news/editorial/38-walking-shiraz.jpg','پیاده‌روی تند بانوی ورزشکار در مسیر سرسبز شیراز','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_walking_and_strength','combine-walking-and-strength-training-week','پیاده‌روی و بدنسازی را در یک هفته چطور کنار هم بگذاریم؟','پیاده‌روی می‌تواند بخشی از فعالیت هوازی باشد و تمرین قدرتی هم گروه‌های عضلانی را هدف بگیرد؛ لازم نیست همهٔ فعالیت‌ها در یک جلسه جمع شوند.','## دو نوع فعالیت، دو نقش متفاوت'||char(10)||char(10)||'راهنمای WHO برای بزرگسالان ترکیبی از فعالیت هوازی و تمرین تقویت عضلات را پیشنهاد می‌کند. پیاده‌روی تند برای بسیاری از افراد راه در دسترس‌تری برای فعالیت هوازی است؛ تمرین قدرتی نیز می‌تواند با وزن بدن، کش، دمبل یا دستگاه طراحی شود.'||char(10)||char(10)||'## یک نمونهٔ قابل‌انعطاف'||char(10)||char(10)||'می‌توانید پیاده‌روی کوتاه را در چند روز هفته پخش کنید و دو جلسهٔ قدرتی را در روزهای جداگانه بگذارید. این فقط نمونهٔ چیدمان است؛ زمان و شدت را بر اساس تجربه و ترجیح تنظیم کنید. اگر یک روز برنامه به‌هم خورد، جلسهٔ بعد را دو برابر نکنید.'||char(10)||char(10)||'## برای شروع از کجا کمک بگیریم؟'||char(10)||char(10)||'در باشگاه بدنسازی بانوان از مربی بخواهید جلسه‌ها را با سطح فعلی شما هماهنگ کند. اگر تازه شروع کرده‌اید، زمان و سرعت را کم نگه دارید و تدریجی پیش بروید. شرایط پزشکی، بارداری یا درد پایدار می‌تواند نیازمند توصیهٔ فردی باشد.','راهنمای شیراز','["پیاده روی و بدنسازی","برنامه ورزشی هفتگی بانوان","باشگاه بدنسازی بانوان شیراز"]','[{"title":"Physical activity","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/physical-activity","published":"2024-06-26"},{"title":"WHO Guidelines on Physical Activity and Sedentary Behaviour: At a Glance","publisher":"World Health Organization","url":"https://iris.who.int/bitstream/handle/10665/336656/9789240015128-eng.pdf","published":"2020-11-25"}]','https://mgfitclub.ir/assets/news/editorial/28-walk-and-strength.jpg','ورزشکار بانوان در حال پیاده‌روی روی تردمیل در کنار فضای قدرتی','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_pilates_and_strength','pilates-and-strength-training-complement','پیلاتس و تمرین قدرتی؛ دو روش مکمل یا انتخاب یکی از آن‌ها؟','پیلاتس و بدنسازی اهداف و تجربهٔ متفاوتی دارند. انتخاب یا ترکیب آن‌ها بهتر است بر پایهٔ علاقه، دسترسی و نیاز فردی باشد، نه وعدهٔ نتیجهٔ تضمینی.','## پیلاتس و تمرین با وزنه چه تفاوتی دارند؟'||char(10)||char(10)||'در بسیاری از کلاس‌های پیلاتس، کنترل حرکت، تنفس و هماهنگی بدن محور است. تمرین مقاومتی با ابزارهای مختلف انجام می‌شود و بار را برای تقویت عضلات تنظیم می‌کند. هر دو روش شکل‌های متنوعی دارند و نام کلاس به‌تنهایی محتوای آن را مشخص نمی‌کند.'||char(10)||char(10)||'## آیا می‌شود هر دو را در برنامه داشت؟'||char(10)||char(10)||'بله، بعضی افراد از تنوع این دو نوع کلاس لذت می‌برند؛ اما ترتیب جلسه‌ها، زمان بازیابی و مقدار تمرین باید متناسب باشد. در ابتدا یک هدف عملی انتخاب کنید، مثلاً آشنایی با کلاس یا ساختن عادت هفتگی، و سپس برنامه را تنظیم کنید.'||char(10)||char(10)||'## وعدهٔ درمان یا کاهش وزن ندهیم'||char(10)||char(10)||'مرور چتری سال ۲۰۲۳ شواهدی امیدوارکننده اما با کیفیت پایین تا متوسط را گزارش می‌کند؛ این نتایج تضمین همگانی نیستند. پیلاتس یا تمرین قدرتی جایگزین ارزیابی پزشکی نیست. اگر دنبال کلاس پیلاتس در شیراز هستید، دربارهٔ سطح‌بندی و گزینهٔ ساده‌تر هر حرکت بپرسید.','پیلاتس','["پیلاتس و بدنسازی","باشگاه پیلاتس شیراز","کلاس بدنسازی بانوان"]','[{"title":"Pilates and multiple health outcomes: An umbrella review","publisher":"Journal of Science and Medicine in Sport via PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37076415/","published":"2023-04-01"},{"title":"Physical activity","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/physical-activity","published":"2024-06-26"}]','https://mgfitclub.ir/assets/news/editorial/22-pilates-control.jpg','اجرای حرکت کنترل‌شدهٔ پیلاتس روی مت در کلاس بانوان','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_pilates_evidence','what-pilates-research-can-and-cannot-tell-us','شواهد علمی دربارهٔ پیلاتس چه می‌گویند و چه چیزی را ثابت نمی‌کنند؟','مرورهای پژوهشی از پیامدهای امیدوارکننده‌ای گزارش می‌کنند، اما قطعیت شواهد در بسیاری از موضوع‌ها محدود است؛ بنابراین باید از وعدهٔ درمان قطعی پرهیز کرد.','## یک مرور پژوهشی را درست بخوانیم'||char(10)||char(10)||'مرور چتری سال ۲۰۲۳، مرورهای نظام‌مند متعددی دربارهٔ پیلاتس و پیامدهای گوناگون را جمع‌بندی کرد. نویسندگان برای بسیاری از مرورها کیفیت پایین یا بسیار پایین گزارش کردند و قطعیت شواهد را در دامنهٔ پایین تا متوسط دانستند. نتیجهٔ امیدوارکننده با اثبات قطعی اثر برای همه یکسان نیست.'||char(10)||char(10)||'## نتیجه برای انتخاب کلاس چیست؟'||char(10)||char(10)||'بپرسید آیا مربی حرکت‌ها را مرحله‌بندی می‌کند، امکان تغییر دامنه یا استراحت وجود دارد و سطح گروه با تجربهٔ شما هم‌خوان است. این معیارها برای تجربهٔ تمرین مهم‌اند، اما جای توصیهٔ بالینی را نمی‌گیرند.'||char(10)||char(10)||'## مرز آموزش ورزشی و درمان'||char(10)||char(10)||'اگر درد مزمن، آسیب یا بیماری دارید، پیش از انتخاب نوع تمرین با متخصص مشورت کنید. مطلب تحریریهٔ باشگاه ام‌جی شیراز اطلاعات عمومی است و تشخیص یا برنامهٔ درمانی ارائه نمی‌دهد. هر علامت غیرمعمول یا درد تیز را به مربی بگویید و تمرین را متوقف کنید.','پیلاتس','["فواید پیلاتس شواهد علمی","کلاس پیلاتس بانوان شیراز","پیلاتس و سلامت"]','[{"title":"Pilates and multiple health outcomes: An umbrella review","publisher":"Journal of Science and Medicine in Sport via PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/37076415/","published":"2023-04-01"}]','https://mgfitclub.ir/assets/news/editorial/27-cooldown.jpg','هنرجوی پیلاتس پس از کلاس حرکت آرام روی مت انجام می‌دهد','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_reps_in_reserve','repetitions-in-reserve-simple-effort-scale','چند تکرار دیگر می‌توانستم؟ راه سادهٔ سنجش تلاش در تمرین','مقیاس تکرار باقی‌مانده کمک می‌کند سختی ست را توصیف کنید؛ ابزار ثبت تجربه است، نه عدد پزشکی یا مجوزی برای تمرین تا مرز از دست‌دادن فرم.','## مفهوم تکرار باقی‌مانده'||char(10)||char(10)||'پس از پایان ست از خود بپرسید: با همان دامنه و تکنیک حدوداً چند تکرار دیگر ممکن بود؟ اگر جواب صفر است، احتمالاً به ناتوانی نزدیک شده‌اید؛ اگر چند تکرار، ست سبک‌تر بوده است. برای تازه‌کارها این فقط تخمین ذهنی است.'||char(10)||char(10)||'## چطور از این برآورد استفاده کنیم؟'||char(10)||char(10)||'در دفتر تمرین می‌توانید کنار حرکت یادداشت کنید ست آسان، متوسط یا سخت بود. مربی با این اطلاعات کمک می‌کند بار یا تعداد تکرار مناسب را انتخاب کنید. برای آزمودن تخمین وزنه را آن‌قدر زیاد نکنید که فرم به‌هم بریزد.'||char(10)||char(10)||'## چرا هر ست نباید آزمون باشد؟'||char(10)||char(10)||'جمع‌بندی ACSM در ۲۰۲۶ تأکید می‌کند تمرین تا ناتوانی و تکنیک‌های پیشرفته برای همه الزاماً مزیت پیوسته ایجاد نمی‌کنند. فشار تمرین باید قابل‌مدیریت و تکرارپذیر باشد. در صورت بیماری یا آسیب، روش ارزیابی تلاش را با متخصص هماهنگ کنید.','بدنسازی','["تکرار باقی مانده در بدنسازی","شدت ست تمرین","مربی بدنسازی بانوان شیراز"]','[{"title":"5 Things to Know About Creating an Effective Resistance Training Plan","publisher":"American College of Sports Medicine","url":"https://www.acsm.org/effective-resistance-training-program-infographic/","published":"2026-03"}]','https://mgfitclub.ir/assets/news/editorial/39-coach-goals.jpg','گفت‌وگوی مربی با ورزشکار برای تنظیم هدف و شدت تمرین','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_between_set_rest','how-long-to-rest-between-strength-sets','بین ست‌های بدنسازی چقدر استراحت کنیم؟ عدد جادویی وجود ندارد','زمان استراحت به حرکت، شدت، آمادگی و هدف جلسه وابسته است. نشانهٔ کاربردی این است که پیش از ست بعدی بتوانید دوباره با کنترل و تمرکز شروع کنید.','## استراحت بخشی از برنامه است'||char(10)||char(10)||'فاصلهٔ بین دو ست فرصتی برای بازیابی و آماده‌شدن برای اجرای بعدی است. یک عدد ثابت برای همهٔ حرکت‌ها و افراد پاسخ‌گوی تفاوت بار، نفس‌گیری و تجربه نیست. ست‌های دشوارتر ممکن است به فرصت بیشتری نیاز داشته باشند تا فرم حفظ شود.'||char(10)||char(10)||'## نشانه‌های شروع ست بعدی'||char(10)||char(10)||'اگر هنوز دستور مربی را دنبال نمی‌کنید، دامنهٔ حرکت کنترل نمی‌شود یا نفس‌گیری آرام نشده، کمی بیشتر استراحت کنید. در کلاس گروهی می‌توانید نسخهٔ ساده‌تر حرکت را انتخاب کنید یا یک دور را کنار بگذارید. کیفیت حرکت را فدای همگام‌شدن با دیگران نکنید.'||char(10)||char(10)||'## برنامهٔ شخصی از مربی بگیرید'||char(10)||char(10)||'استراحت‌های برنامه باید با هدف و شرایط ورزشکار هماهنگ شود. اگر در جلسه‌ها همواره برای بازیابی مشکل دارید، بار، تعداد ست و ترتیب حرکات را با مربی مرور کنید. علائم نگران‌کننده نیازمند توقف و رسیدگی تخصصی است.','بدنسازی','["استراحت بین ست بدنسازی","زمان استراحت تمرین قدرتی","باشگاه بدنسازی ام جی"]','[{"title":"ACSM Position Stands","publisher":"American College of Sports Medicine","url":"https://acsm.org/education-resources/pronouncements-scientific-communications/position-stands/","published":"2026"},{"title":"Physical activity","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/physical-activity","published":"2024-06-26"}]','https://mgfitclub.ir/assets/news/editorial/29-recovery-between-sets.jpg','ورزشکار در باشگاه میان دو ست با راهنمایی مربی استراحت می‌کند','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_strength_warmup','warm-up-before-strength-training','پیش از تمرین قدرتی چه گرم‌کردنی انجام دهیم؟','چند دقیقه فعالیت سبک و تمرین الگوی حرکت می‌تواند بدن را آماده کند؛ گرم‌کردن قرار نیست خودش به تمرینی خسته‌کننده تبدیل شود.','## گرم‌کردن را با برنامهٔ همان روز مرتبط کنید'||char(10)||char(10)||'با راه‌رفتن آرام یا حرکت سبک شروع کنید، سپس چند تکرار بدون بار یا با بار کم از حرکت‌های جلسه انجام دهید. اگر روز تمرین پایین‌تنه است، حرکات آماده‌سازی را با همان الگو هماهنگ کنید. برای کلاس پیلاتس از مربی دربارهٔ آماده‌سازی همان جلسه بپرسید.'||char(10)||char(10)||'## لازم نیست کپی برنامهٔ دیگری باشد'||char(10)||char(10)||'مدت و جزئیات گرم‌کردن با تجربه، محیط و نوع تمرین فرق می‌کند. هدف این نیست که پیش از ست اصلی خسته شوید؛ باید بتوانید راحت صحبت کنید و حرکت را کنترل کنید. در گرمای شیراز شدت آغاز را محافظه‌کارانه نگه دارید.'||char(10)||char(10)||'## علائم را نادیده نگیرید'||char(10)||char(10)||'اگر در گرم‌کردن درد تیز، ضعف ناگهانی یا سرگیجه ایجاد شد ادامه ندهید. مربی می‌تواند دامنه را کم کند یا حرکت دیگری پیشنهاد دهد، اما علائم پزشکی نیازمند ارزیابی متخصص است.','بدنسازی','["گرم کردن قبل بدنسازی","آماده سازی برای تمرین","باشگاه بدنسازی بانوان"]','[{"title":"Physical Activity Guidelines for Americans, 2nd edition","publisher":"U.S. Department of Health and Human Services","url":"https://health.gov/our-work/nutrition-physical-activity/physical-activity-guidelines/current-guidelines","published":"2018-12-01"},{"title":"Physical activity","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/physical-activity","published":"2024-06-26"}]','https://mgfitclub.ir/assets/news/editorial/26-warmup.jpg','بانوی ورزشکار با راهنمایی مربی پیش از جلسه تمرین گرم می‌کند','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_cooldown_after_class','cooldown-after-group-fitness-class','بعد از کلاس گروهی چه کنیم؟ راهنمای پایان آرام تمرین','پایان جلسه فرصت خوبی برای کم‌کردن تدریجی شدت و توجه به حال عمومی است؛ کشش اجباری یا ادامه‌دادن با وجود درد لازم نیست.','## از حرکت سریع به توقف ناگهانی نروید'||char(10)||char(10)||'اگر کلاس بخش هوازی داشته، چند دقیقه حرکت سبک‌تر مانند راه‌رفتن آرام انجام دهید تا جلسه به‌تدریج پایان یابد. سپس وسایل را مرتب کنید، آب بنوشید و اجازه دهید تنفس به وضعیت راحت برگردد. این پیشنهاد کلی است و روال پزشکی ثابت برای همه نیست.'||char(10)||char(10)||'## کشش باید راحت باشد'||char(10)||char(10)||'اگر دوست دارید حرکت‌های کششی آرام را در دامنه‌ای انجام دهید که درد ایجاد نکند. کشش شدید یا همراه با فشار الزاماً به معنی نتیجهٔ بهتر نیست. در پیلاتس نیز راحتی و کنترل را بر رسیدن به شکل ظاهری خاص اولویت دهید.'||char(10)||char(10)||'## بازیابی را با دیگران نسنجید'||char(10)||char(10)||'خستگی افراد متفاوت است. اگر تهوع، سرگیجه، درد قفسهٔ سینه یا تنگی نفس غیرمعمول دارید تمرین را متوقف کنید و کمک بگیرید. تازه‌کاران در کلاس گروهی شیراز می‌توانند نسخهٔ کم‌فشار و استراحت را انتخاب کنند.','تمرین گروهی','["بعد از ورزش چه کنیم","پایان تمرین گروهی","کلاس ورزشی بانوان شیراز"]','[{"title":"Measuring Physical Activity Intensity","publisher":"Centers for Disease Control and Prevention","url":"https://www.cdc.gov/physicalactivity/basics/measuring/index.html","published":"2024-04-23"},{"title":"Physical activity","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/physical-activity","published":"2024-06-26"}]','https://mgfitclub.ir/assets/news/editorial/34-group-cardio.jpg','گروه بانوان بعد از کلاس هوازی به آرامی حرکت می‌کنند','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_resistance_bands','resistance-band-strength-training-guide','تمرین با کش مقاومتی؛ چطور سطح دشواری را ایمن تنظیم کنیم؟','کش‌ها ابزار قابل‌حملی برای تمرین مقاومتی‌اند. انتخاب کش و دامنه باید امکان حفظ کنترل را بدهد؛ کش ضخیم‌تر همیشه انتخاب مناسب‌تری نیست.','## از کش سبک و اتصال مطمئن شروع کنید'||char(10)||char(10)||'پیش از تمرین کش را از نظر ترک و فرسودگی بررسی کنید و فقط از محل اتصال مطمئن استفاده کنید. کشی انتخاب کنید که مسیر رفت‌وبرگشت را آرام کنترل کنید. اگر کش می‌لغزد یا به بدن برمی‌گردد، حرکت را متوقف کنید.'||char(10)||char(10)||'## دشواری را چطور تنظیم کنیم؟'||char(10)||char(10)||'فاصله از نقطهٔ اتصال، طول کش، دامنه و تعداد تکرار بر مقاومت اثر می‌گذارند. ابتدا فرم را یاد بگیرید و سپس تنها یک عامل را کمی تغییر دهید. ACSM ابزارهایی مثل کش و وزن بدن را گزینه‌هایی برای تمرین قدرتی می‌داند؛ تجهیزات گران‌قیمت شرط شروع نیستند.'||char(10)||char(10)||'## تمرین خانگی یا باشگاه؟'||char(10)||char(10)||'کش برای خانه یا سالن کاربرد دارد، اما برنامه به هدف بستگی دارد. اگر دربارهٔ نحوهٔ مهار کش مطمئن نیستید، از مربی باشگاه ام‌جی بخواهید روش ایمن را نشان دهد. محدودیت پزشکی نیازمند تعدیل فردی است.','بدنسازی','["تمرین با کش مقاومتی","کش بدنسازی بانوان","تمرین قدرتی در خانه"]','[{"title":"5 Things to Know About Creating an Effective Resistance Training Plan","publisher":"American College of Sports Medicine","url":"https://www.acsm.org/effective-resistance-training-program-infographic/","published":"2026-03"},{"title":"WHO Guidelines on Physical Activity and Sedentary Behaviour: At a Glance","publisher":"World Health Organization","url":"https://iris.who.int/bitstream/handle/10665/336656/9789240015128-eng.pdf","published":"2020-11-25"}]','https://mgfitclub.ir/assets/news/editorial/32-resistance-band.jpg','ورزشکار بانوان تمرین قایقی با کش را زیر نظر مربی انجام می‌دهد','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_trx_body_angle','trx-body-angle-progression-for-beginners','در تمرین TRX زاویهٔ بدن را چطور تغییر دهیم؟','در بسیاری از حرکات TRX تغییر جای پا نسبت به نقطهٔ اتصال، دشواری حرکت را عوض می‌کند. با دامنهٔ کم و کنترل‌شده شروع کنید.','## چرا زاویه در TRX اهمیت دارد؟'||char(10)||char(10)||'بخشی از بار تمرین TRX با وضعیت بدن و فاصله از نقطهٔ اتصال تغییر می‌کند. هرچه بدن در بعضی الگوها افقی‌تر شود، حرکت ممکن است دشوارتر احساس شود؛ اثر دقیق به نوع حرکت، توان و تکنیک فرد بستگی دارد.'||char(10)||char(10)||'## یک مرحله در هر بار تغییر'||char(10)||char(10)||'برای یادگیری ابتدا بدن را عمودی‌تر نگه دارید، بندها را متناسب تنظیم کنید و حرکت را با دامنهٔ کوتاه اجرا کنید. اگر شانه‌ها بالا می‌روند، تنه می‌چرخد یا بندها شل و نامتقارن می‌شوند، نسخهٔ ساده‌تر را انتخاب کنید. نقطهٔ اتصال و فضای اطراف را پیش از شروع بررسی کنید.'||char(10)||char(10)||'## نکتهٔ ایمنی برای کلاس TRX'||char(10)||char(10)||'به بند یا اتصالی که لق یا آسیب‌دیده است تکیه نکنید. فضای کافی و کف غیرلغزنده انتخاب کنید و حرکت را کنترل‌شده انجام دهید. اگر TRX برایتان تازه است، کلاس مقدماتی و نظارت مربی را به تقلید از دیگران ترجیح دهید.','TRX','["تمرین TRX مبتدی","تنظیم زاویه در TRX","باشگاه TRX شیراز"]','[{"title":"5 Things to Know About Creating an Effective Resistance Training Plan","publisher":"American College of Sports Medicine","url":"https://www.acsm.org/effective-resistance-training-program-infographic/","published":"2026-03"},{"title":"Physical activity","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/physical-activity","published":"2024-06-26"}]','https://mgfitclub.ir/assets/news/editorial/23-trx-progression.jpg','ورزشکار بانوان حرکت لانج کمکی TRX را با نظارت مربی تمرین می‌کند','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_group_class_modifications','how-to-modify-group-fitness-exercises','در کلاس گروهی چطور حرکت را متناسب با سطح خود ساده کنیم؟','در کلاس گروهی لازم نیست همه با سرعت و دامنهٔ یکسان تمرین کنند. تغییر یک متغیر مثل دامنه، سرعت یا ابزار می‌تواند حرکت را قابل‌مدیریت‌تر کند.','## سه راه ساده برای تعدیل حرکت'||char(10)||char(10)||'می‌توانید دامنه را کوتاه‌تر کنید، سرعت را کم کنید یا ابزار سبک‌تری بردارید؛ انتخاب دقیق به حرکت بستگی دارد. پیش از کلاس به مربی بگویید تازه‌کار هستید یا محدودیتی دارید تا نسخهٔ جایگزین را بشناسید.'||char(10)||char(10)||'## کلاس گروهی رقابت نیست'||char(10)||char(10)||'پژوهش‌ها دربارهٔ ماندگاری در فعالیت گروهی نقش خودباوری، فضای اجتماعی و رفتار مربی را بررسی کرده‌اند؛ نتیجه‌ها وابسته به شرایط و کیفیت مطالعه‌اند. همراهی گروه برای بعضی‌ها انگیزه‌بخش است، ولی لزوماً برای همه بهترین قالب نیست.'||char(10)||char(10)||'## چه زمانی توقف کنیم؟'||char(10)||char(10)||'سوزش معمول عضله را با درد تیز یا ناپایداری یکی ندانید. اگر حرکت دردناک است آن را متوقف کنید و از مربی گزینهٔ امن‌تر بخواهید. محیط تمرین مناسب فضایی است که بتوانید سؤال کنید و مجبور به ادامهٔ نسخهٔ ناسازگار با توان امروزتان نباشید.','تمرین گروهی','["ساده کردن حرکت در کلاس ورزشی","تمرین گروهی بانوان","باشگاه بانوان شیراز"]','[{"title":"Facilitators of Attendance and Adherence to Group-Based Physical Activity for Older Adults: A Literature Synthesis","publisher":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/28595021/","published":"2017-06-14"},{"title":"Assessing the psychosocial factors associated with adherence to exercise referral schemes: A systematic review","publisher":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/30742334/","published":"2019-02-07"}]','https://mgfitclub.ir/assets/news/editorial/24-group-class.jpg','گروهی از بانوان در کلاس قدرتی کم‌فشار با مربی تمرین می‌کنند','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_exercise_habit','build-a-realistic-gym-habit-weekly-routine','چطور عادت باشگاه رفتن را با برنامهٔ واقعی زندگی بسازیم؟','شروع کوچک، ساعت ثابت و انتخاب کلاسی که از آن لذت می‌برید معمولاً از چیدن برنامهٔ سنگین اما غیرقابل‌اجرا کاربردی‌تر است.','## برنامه را از تقویم خود شروع کنید'||char(10)||char(10)||'به‌جای اینکه از ابتدا هر روز را به ورزش اختصاص دهید، دو بازهٔ واقع‌بینانه در هفته پیدا کنید. مسیر رفت‌وآمد، مسئولیت خانه، ساعت کاری و مدت تمرین را وارد تصمیم کنید. اگر فقط یک جلسه انجام شد، آن را شکست تلقی نکنید؛ بازگشت به روال مهم‌تر از کامل‌بودن برنامه است.'||char(10)||char(10)||'## یک نشانهٔ ثابت بسازید'||char(10)||char(10)||'لباس یا کیف تمرین را از شب قبل آماده کنید، جلسه را در تقویم ثبت کنید و برای روز شلوغ گزینهٔ کوتاه‌تری داشته باشید. کلاس گروهی برای برخی ساختار زمانی فراهم می‌کند، ولی تمرین انفرادی هم برای دیگران مناسب‌تر است.'||char(10)||char(10)||'## هدف را منعطف نگه دارید'||char(10)||char(10)||'به‌جای تمرکز دائمی بر وزن یا ظاهر، حضور در جلسه‌ها و یادگیری حرکت‌ها را هم ثبت کنید. راهنمای عمومی سلامت می‌گوید هر مقدار فعالیت بهتر از بی‌تحرکی کامل است؛ نوع مناسب به شرایط فرد بستگی دارد.','راهنمای شیراز','["عادت باشگاه رفتن","برنامه تمرین بانوان","باشگاه ام جی شیراز"]','[{"title":"Physical activity","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/physical-activity","published":"2024-06-26"},{"title":"Adherence to exercise referral schemes by participants—what do providers and commissioners need to know?","publisher":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/26944952/","published":"2016-03-08"}]','https://mgfitclub.ir/assets/news/editorial/33-training-log.jpg','بانوی ورزشکار برنامه و یادداشت تمرین هفتگی‌اش را مرور می‌کند','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_balance_older_adults','balance-and-strength-training-older-women','تمرین تعادل و قدرت برای بانوان سالمند؛ شروع با حمایت مربی','برای افراد ۶۵ سال به بالا، راهنمای CDC علاوه بر فعالیت هوازی و تقویت عضلات، فعالیت‌های بهبود تعادل را هم مطرح می‌کند؛ انتخاب حرکت باید با توان فرد هماهنگ باشد.','## سه جزء فعالیت هفتگی'||char(10)||char(10)||'CDC برای بزرگسالان ۶۵ سال به بالا فعالیت هوازی، تقویت عضله و فعالیت‌های تعادلی را در برنامهٔ هفتگی ذکر می‌کند. مقدار و شکل فعالیت باید با توان فرد تناسب داشته باشد؛ این توصیه به معنی مناسب‌بودن یک حرکت مشخص برای همه نیست.'||char(10)||char(10)||'## از حرکت حمایت‌شده شروع کنید'||char(10)||char(10)||'در محیط امن می‌توان با نظارت مربی روی جابه‌جایی وزن، برخاستن کنترل‌شده یا راه‌رفتن پاشنه‌به‌پنجه تمرین کرد. نزدیک‌بودن تکیه‌گاه و حذف موانع اهمیت دارد. اگر تعادل امروز کمتر است، از تکیه‌گاه استفاده کنید و برای دشوارترکردن حرکت عجله نکنید.'||char(10)||char(10)||'## پیش از تغییر برنامه سؤال بپرسید'||char(10)||char(10)||'سابقهٔ افتادن، سرگیجه، بیماری یا درد ممکن است نیازمند ارزیابی و برنامهٔ فردی باشد. پیش از تمرین جدید با پزشک یا متخصص توان‌بخشی مشورت کنید. این راهنما تشخیص یا درمان نیست.','بدنسازی','["تمرین تعادل سالمندان","بدنسازی بانوان بالای ۶۵ سال","باشگاه بانوان شیراز"]','[{"title":"Older Adult Activity: An Overview","publisher":"Centers for Disease Control and Prevention","url":"https://www.cdc.gov/physical-activity-basics/guidelines/older-adults.html","published":"2025-12-04"},{"title":"Physical activity","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/physical-activity","published":"2024-06-26"}]','https://mgfitclub.ir/assets/news/editorial/31-balance-training.jpg','بانوی سالمند با تکیه‌گاه صندلی و حضور مربی تمرین تعادل می‌کند','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_first_gym_visit','first-gym-visit-checklist-women-shiraz','اولین بازدید از باشگاه بانوان شیراز؛ چه چیزهایی را بررسی کنیم؟','پیش از خرید عضویت، یک بازدید کوتاه کمک می‌کند ساعت کلاس، فضای تمرین، نظافت، راهنمایی مربی و دسترسی را با نیاز خود مقایسه کنید.','## تجربهٔ واقعی ساعت موردنظر را ببینید'||char(10)||char(10)||'اگر می‌توانید در همان ساعتی بازدید کنید که قصد تمرین دارید. به ظرفیت کلاس، چیدمان وسایل و امکان جابه‌جایی امن دقت کنید. از کارکنان دربارهٔ شیوهٔ رزرو، زمان‌بندی، قوانین کنسلی و دسترسی به مربی سؤال کنید و اطلاعات شفاهی را با مقررات نوشته‌شده تطبیق دهید.'||char(10)||char(10)||'## معیارهای انتخاب را شخصی کنید'||char(10)||char(10)||'برای یک نفر نزدیکی مسیر مهم است؛ برای دیگری ساعت کلاس پیلاتس، تجهیزات TRX یا حریم مناسب تمرین. عنوان بهترین باشگاه بانوان شیراز فقط وقتی برای شما معنا دارد که معیارهایتان روشن باشد. یک عکس یا نظر آنلاین کیفیت تجربهٔ روزمره را تضمین نمی‌کند.'||char(10)||char(10)||'## پیش از تصمیم چه بپرسیم؟'||char(10)||char(10)||'آیا سطح مبتدی و حرکت جایگزین وجود دارد؟ در صورت نیاز چگونه از مربی کمک می‌گیرم؟ هزینه و شرایط عضویت چیست؟ این صفحه ادعای برتری قطعی برای باشگاه خاصی ندارد و راهنمای انتخاب آگاهانه است.','راهنمای شیراز','["اولین بازدید باشگاه بانوان","بهترین باشگاه بانوان شیراز","باشگاه ام جی فرهنگ شهر"]','[{"title":"Adherence to exercise referral schemes by participants—what do providers and commissioners need to know?","publisher":"PubMed","url":"https://pubmed.ncbi.nlm.nih.gov/26944952/","published":"2016-03-08"},{"title":"Physical activity","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/physical-activity","published":"2024-06-26"}]','https://mgfitclub.ir/assets/news/editorial/37-machine-coaching.jpg','مربی باشگاه امکانات دستگاه را برای ورزشکار تازه‌وارد توضیح می‌دهد','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_training_log','how-to-track-strength-workout-progress','دفتر تمرین بدنسازی را با چه اطلاعاتی پر کنیم؟','ثبت حرکت، بار، تکرار و حس سختی جلسه کمک می‌کند روند تمرین را مرور کنید؛ لازم نیست هر بار رکورد جدیدی ثبت شود.','## اطلاعات پایه و کوتاه ثبت کنید'||char(10)||char(10)||'نام حرکت، تعداد ست و تکرار، وزنه یا رنگ کش، تاریخ و یادداشتی کوتاه دربارهٔ کیفیت فرم را بنویسید. می‌توانید سطح سختی را با واژه‌های آسان، متوسط یا سخت مشخص کنید. همین داده‌ها برای گفت‌وگو با مربی و یادآوری جلسهٔ قبلی مفیدند.'||char(10)||char(10)||'## دنبال روند باشید، نه مقایسه'||char(10)||char(10)||'پیشرفت ممکن است در اجرای روان‌تر، حضور منظم‌تر یا افزایش تدریجی بار دیده شود. تغییر خواب، استرس یا زمان جلسه هم بر عملکرد روزانه اثر می‌گذارد؛ پس یک تمرین ضعیف به معنی شکست برنامه نیست. ACSM بر استمرار و ساده‌بودن برنامه مقاومتی تأکید می‌کند.'||char(10)||char(10)||'## چه چیزی را ثبت نکنیم؟'||char(10)||char(10)||'اگر اندازه‌گیری‌ها اضطراب ایجاد می‌کنند، آن‌ها را حذف کنید. جزئیات پزشکی خصوصی را در دفتر عمومی باشگاه ننویسید و اطلاعات حساس را به اشتراک نگذارید. هدف دفتر تمرین، کمک به یادگیری و پیگیری انتخاب‌های خودتان است.','بدنسازی','["دفتر ثبت تمرین بدنسازی","پیگیری پیشرفت ورزشی","برنامه تمرینی بانوان شیراز"]','[{"title":"5 Things to Know About Creating an Effective Resistance Training Plan","publisher":"American College of Sports Medicine","url":"https://www.acsm.org/effective-resistance-training-program-infographic/","published":"2026-03"},{"title":"Physical activity","publisher":"World Health Organization","url":"https://www.who.int/news-room/fact-sheets/detail/physical-activity","published":"2024-06-26"}]','https://mgfitclub.ir/assets/news/editorial/33-training-log.jpg','بانوی ورزشکار نکات جلسهٔ تمرین را در دفتر ثبت می‌کند','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER)),
('mg_editorial_r2_acsm_2026_strength','acsm-2026-resistance-training-guidance-explained','راهنمای تازهٔ ACSM در ۲۰۲۶ دربارهٔ تمرین مقاومتی به زبان ساده','پیام محوری خلاصهٔ تازهٔ ACSM برای بزرگسالان سالم این است: منظم تمرین کنید، برنامه را با هدف هماهنگ کنید و از پیچیدگی غیرضروری نترسید.','## تغییر مهم، ساده‌ترشدن نقطهٔ شروع است'||char(10)||char(10)||'کالج پزشکی ورزشی آمریکا در خلاصهٔ منتشرشده در ۲۰۲۶ بر استمرار، شخصی‌سازی بر اساس هدف و تدریجی‌بودن تمرین تأکید می‌کند. ابزارهای ساده مانند وزن بدن و کش نیز می‌توانند برای تمرین مقاومتی استفاده شوند؛ باشگاه شرط ضروری شروع نیست.'||char(10)||char(10)||'## هدف‌ها نسخهٔ یکسان ندارند'||char(10)||char(10)||'برنامهٔ مرتبط با قدرت، رشد عضله یا توان انفجاری می‌تواند از بار و شیوه‌های متفاوتی استفاده کند. اعداد راهنما برای بزرگسالان سالم و طراحی تمرین‌اند، نه نسخهٔ آماده برای هر فرد. سابقه، مهارت، امکانات و وضعیت پزشکی اهمیت دارند.'||char(10)||char(10)||'## ترجمهٔ این راهنما به تمرین روزمره'||char(10)||char(10)||'برای ورزشکار باشگاه بدنسازی ام‌جی کاربرد ساده این است: حرکت‌ها را درست یاد بگیرید، برنامه‌ای قابل‌ادامه انتخاب کنید و تغییرات را مرحله‌ای انجام دهید. لازم نیست هر جلسه وسیله یا تکنیک پیشرفته داشته باشد. در صورت بیماری یا آسیب با متخصص مربوط مشورت کنید.','بدنسازی','["راهنمای تمرین مقاومتی ACSM 2026","باشگاه بدنسازی ام جی","بدنسازی بانوان شیراز"]','[{"title":"5 Things to Know About Creating an Effective Resistance Training Plan","publisher":"American College of Sports Medicine","url":"https://www.acsm.org/effective-resistance-training-program-infographic/","published":"2026-03"},{"title":"Board of Trustees Q4 Approved Actions","publisher":"American College of Sports Medicine","url":"https://acsm.org/board-of-trustees-q4-approved-actions/","published":"2026-01-30"}]','https://mgfitclub.ir/assets/news/editorial/40-dumbbell-coach.jpg','مربی خانم اجرای تمرین مقاومتی دمبل را به ورزشکار نشان می‌دهد','تحریریه MG FitClub','published',CAST(strftime('%s','now') AS INTEGER),CAST(strftime('%s','now') AS INTEGER));
UPDATE news_editorial_articles SET image_url='https://mgfitclub.ir/assets/news/editorial/35-hip-hinge.jpg',image_alt='ورزشکار در حال ثبت روند تمرین قدرتی در فضای باشگاه' WHERE id='mg_editorial_r2_training_log';
UPDATE news_editorial_articles SET image_url='https://mgfitclub.ir/assets/news/editorial/36-home-band.jpg',image_alt='تمرین قدرتی با کش مقاومتی برای بانوان' WHERE id='mg_editorial_r2_acsm_2026_strength';
